alter table public.daily_task_items add column source_submission_id uuid, add column source_question_id uuid, add column source_line_ordinal integer, add constraint daily_task_items_source_identity_check check ((source_submission_id is null and source_question_id is null and source_line_ordinal is null) or (source_submission_id is not null and source_question_id is not null and source_line_ordinal > 0)), add constraint daily_task_items_carried_source_check check (carried_from_id is null or source_submission_id is null), add constraint daily_task_items_source_answer_fk foreign key (tenant_id, source_submission_id, source_question_id) references public.daily_submission_answers (tenant_id, submission_id, question_id) on delete restrict;
create unique index daily_task_items_source_identity_uniq on public.daily_task_items (tenant_id, source_submission_id, source_question_id, source_line_ordinal) where source_submission_id is not null and source_question_id is not null and source_line_ordinal is not null;
create index daily_task_items_source_submission_idx on public.daily_task_items (tenant_id, source_submission_id) where source_submission_id is not null;
do $$
declare v_tenant_id uuid; v_candidate_tenant_count integer; v_question_count integer; v_conflict record;
begin
 select count(*), min(candidate.tenant_id::text)::uuid into v_candidate_tenant_count, v_tenant_id from (select q.tenant_id from public.daily_questions q where q.question_text in ('¿En que trabajaste ayer?', '¿En que trabajarás hoy?', '¿Tienes algún bloqueo?') group by q.tenant_id having count(*) = 3 and count(*) filter (where q.question_text = '¿En que trabajaste ayer?') = 1 and count(*) filter (where q.question_text = '¿En que trabajarás hoy?') = 1 and count(*) filter (where q.question_text = '¿Tienes algún bloqueo?') = 1) candidate;
 if v_candidate_tenant_count <> 1 then raise exception 'Daily Spanish semantic-key migration requires exactly one unambiguous intended catalog'; end if;
 select count(*) into v_question_count from public.daily_questions q where q.tenant_id = v_tenant_id and q.question_text in ('¿En que trabajaste ayer?', '¿En que trabajarás hoy?', '¿Tienes algún bloqueo?');
 if v_question_count <> 3 then raise exception 'Daily Spanish semantic-key migration found an ambiguous intended catalog'; end if;
 alter table public.daily_questions disable trigger prevent_daily_question_semantic_change;
 update public.daily_questions q set semantic_key = null, is_active = false, deactivated_at = coalesce(q.deactivated_at, clock_timestamp()) where q.tenant_id = v_tenant_id and (q.question_text, q.semantic_key) in (('What did you complete since your last update?', 'completed_work'), ('What will you work on next?', 'planned_work'), ('Are there any blockers or risks?', 'blockers')) and not exists (select 1 from public.team_daily_questions tdq where tdq.tenant_id = q.tenant_id and tdq.question_id = q.id);
 for v_conflict in select q.id, q.question_text, q.semantic_key, q.is_active from public.daily_questions q where q.tenant_id = v_tenant_id and q.semantic_key in ('completed_work', 'planned_work', 'blockers') and q.question_text not in ('¿En que trabajaste ayer?', '¿En que trabajarás hoy?', '¿Tienes algún bloqueo?') loop if (v_conflict.question_text, v_conflict.semantic_key) not in (('What did you complete since your last update?', 'completed_work'), ('What will you work on next?', 'planned_work'), ('Are there any blockers or risks?', 'blockers')) or exists (select 1 from public.team_daily_questions tdq where tdq.tenant_id = v_tenant_id and tdq.question_id = v_conflict.id) then raise exception 'Daily Spanish semantic-key migration found an ambiguous semantic-key conflict'; end if; end loop;
 update public.daily_questions q set semantic_key = case q.question_text when '¿En que trabajaste ayer?' then 'completed_work' when '¿En que trabajarás hoy?' then 'planned_work' when '¿Tienes algún bloqueo?' then 'blockers' end where q.tenant_id = v_tenant_id and q.question_text in ('¿En que trabajaste ayer?', '¿En que trabajarás hoy?', '¿Tienes algún bloqueo?') and q.semantic_key is distinct from case q.question_text when '¿En que trabajaste ayer?' then 'completed_work' when '¿En que trabajarás hoy?' then 'planned_work' when '¿Tienes algún bloqueo?' then 'blockers' end;
 alter table public.daily_questions enable trigger prevent_daily_question_semantic_change;
 alter table public.daily_run_questions disable trigger prevent_daily_run_question_change;
 update public.daily_run_questions rq set semantic_key = q.semantic_key from public.daily_questions q, public.daily_runs r where q.tenant_id = v_tenant_id and q.id = rq.question_id and rq.tenant_id = q.tenant_id and r.tenant_id = rq.tenant_id and r.team_id = rq.team_id and r.id = rq.run_id and q.question_text in ('¿En que trabajaste ayer?', '¿En que trabajarás hoy?', '¿Tienes algún bloqueo?') and rq.semantic_key is distinct from q.semantic_key and r.local_date >= (clock_timestamp() at time zone r.timezone_snapshot)::date and not exists (select 1 from public.daily_submission_runs sr where sr.run_id = rq.run_id);
 alter table public.daily_run_questions enable trigger prevent_daily_run_question_change;
end; $$;
create or replace function private.snapshot_daily_run_questions() returns trigger language plpgsql security definer set search_path = '' as $$ begin insert into public.daily_run_questions (tenant_id, run_id, team_id, question_id, question_text, semantic_key, position) select new.tenant_id, new.id, new.team_id, q.id, q.question_text, q.semantic_key, tdq.position from public.team_daily_questions tdq join public.daily_questions q on q.tenant_id = tdq.tenant_id and q.id = tdq.question_id where tdq.team_id = new.team_id and tdq.tenant_id = new.tenant_id and q.is_active order by tdq.position; return new; end; $$;
with source_answers as (select a.tenant_id, sr.team_id, a.user_id, r.local_date as logical_date, a.submission_id, a.question_id, a.answer_text from public.daily_submission_answers a join public.daily_submission_runs sr on sr.tenant_id = a.tenant_id and sr.submission_id = a.submission_id and sr.user_id = a.user_id join public.daily_runs r on r.tenant_id = sr.tenant_id and r.id = sr.run_id and r.team_id = sr.team_id join public.daily_questions q on q.tenant_id = a.tenant_id and q.id = a.question_id and q.semantic_key = 'planned_work' join public.team_daily_schedules s on s.tenant_id = sr.tenant_id and s.team_id = sr.team_id and s.is_active where r.local_date = (clock_timestamp() at time zone s.timezone_name)::date and 1 = (select count(*) from public.daily_submission_runs only_run where only_run.tenant_id = sr.tenant_id and only_run.submission_id = sr.submission_id) and (select count(*) from regexp_split_to_table(a.answer_text, E'\r?\n') as candidate_lines(line) where btrim(regexp_replace(candidate_lines.line, E'^\s*[-•]\s?', '')) <> '') between 1 and 100 and not exists (select 1 from regexp_split_to_table(a.answer_text, E'\r?\n') as candidate_lines(line) where char_length(btrim(regexp_replace(candidate_lines.line, E'^\s*[-•]\s?', ''))) not between 1 and 400 and btrim(regexp_replace(candidate_lines.line, E'^\s*[-•]\s?', '')) <> '') and not exists (select 1 from public.daily_task_completions completed where completed.tenant_id = sr.tenant_id and completed.team_id = sr.team_id and completed.user_id = a.user_id and completed.logical_date = r.local_date)), source_lines as (select source_answers.*, lines.ordinal::integer as source_line_ordinal, btrim(regexp_replace(lines.line, E'^\s*[-•]\s?', '')) as title from source_answers cross join lateral regexp_split_to_table(source_answers.answer_text, E'\r?\n') with ordinality as lines(line, ordinal)), valid_lines as (select * from source_lines where char_length(title) between 1 and 400), positioned_lines as (select valid_lines.*, coalesce((select max(existing.position) from public.daily_task_items existing where existing.tenant_id = valid_lines.tenant_id and existing.team_id = valid_lines.team_id and existing.user_id = valid_lines.user_id and existing.logical_date = valid_lines.logical_date), 0) + row_number() over (partition by valid_lines.tenant_id, valid_lines.team_id, valid_lines.user_id, valid_lines.logical_date order by valid_lines.submission_id, valid_lines.source_line_ordinal)::integer as position from valid_lines) insert into public.daily_task_items (tenant_id, team_id, user_id, logical_date, title, position, source_submission_id, source_question_id, source_line_ordinal) select tenant_id, team_id, user_id, logical_date, title, position, submission_id, question_id, source_line_ordinal from positioned_lines on conflict (tenant_id, source_submission_id, source_question_id, source_line_ordinal) where source_submission_id is not null and source_question_id is not null and source_line_ordinal is not null do nothing;
drop function if exists public.submit_daily_response_with_tasks(uuid[], jsonb, date, text[]);
create or replace function public.submit_daily_response_with_tasks(p_run_ids uuid[], p_answers jsonb, p_local_date date, p_carried_task_ids uuid[]) returns uuid language plpgsql security definer set search_path = '' as $$ declare v_user_id uuid := auth.uid(); v_tenant_id uuid; v_team_id uuid; v_team_count integer; v_submission_id uuid; v_planned_question_id uuid; v_planned_question_count integer; v_planned_answer text; v_task_titles text[] := array[]::text[]; v_carried_ids uuid[] := coalesce(p_carried_task_ids, array[]::uuid[]); v_expected_carried_ids uuid[] := array[]::uuid[]; v_carried_count integer; v_expected_carried_count integer; v_distinct_carried_count integer; v_position integer; v_schedule record; v_local_now timestamp; begin
 if v_user_id is null or not private.is_internal_user() then raise exception 'An authenticated internal user is required'; end if;
 if p_run_ids is null or cardinality(p_run_ids) = 0 then raise exception 'At least one Daily run is required'; end if;
 if p_local_date is null or p_answers is null or jsonb_typeof(p_answers) <> 'array' then raise exception 'A selected Daily date and answer array are required'; end if;
 select count(distinct r.team_id), min(r.team_id::text)::uuid, min(r.tenant_id::text)::uuid into v_team_count, v_team_id, v_tenant_id from public.daily_runs r where r.id = any(p_run_ids) and (private.is_tenant_admin(r.tenant_id) or private.is_team_member(r.tenant_id, r.team_id));
 if v_team_count <> 1 then raise exception 'Daily responses and activities must belong to exactly one team'; end if; if v_tenant_id is distinct from private.current_tenant_id() then raise exception 'The Daily runs do not belong to the current tenant'; end if;
 select count(distinct rq.question_id), min(rq.question_id::text)::uuid into v_planned_question_count, v_planned_question_id from public.daily_run_questions rq where rq.run_id = any(p_run_ids) and rq.semantic_key = 'planned_work';
 if v_planned_question_count <> 1 then raise exception 'The selected Daily runs must have exactly one planned-work question'; end if;
 select item ->> 'answer' into v_planned_answer from jsonb_array_elements(p_answers) item where (item ->> 'question_id')::uuid = v_planned_question_id limit 1;
 v_task_titles := array(select btrim(regexp_replace(line, E'^\s*[-•]\s?', '')) from regexp_split_to_table(coalesce(v_planned_answer, ''), E'\r?\n') as lines(line) where btrim(regexp_replace(line, E'^\s*[-•]\s?', '')) <> '');
 if cardinality(v_task_titles) not between 1 and 100 or exists (select 1 from unnest(v_task_titles) title where char_length(title) not between 1 and 400) then raise exception 'Daily planned work must contain between 1 and 100 tasks of 1 to 400 characters'; end if;
 select s.* into strict v_schedule from public.team_daily_schedules s join public.teams t on t.tenant_id = s.tenant_id and t.id = s.team_id where s.tenant_id = v_tenant_id and s.team_id = v_team_id and s.is_active and t.archived_at is null and nullif(btrim(s.timezone_name), '') is not null for share;
 begin v_local_now := clock_timestamp() at time zone v_schedule.timezone_name; exception when invalid_parameter_value then raise exception 'The Daily team timezone is invalid'; end;
 if p_local_date <> v_local_now::date or v_local_now::time >= time '16:00' then raise exception 'Daily planned work is closed for the team local date'; end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_tenant_id::text || ':' || v_team_id::text || ':' || p_local_date::text || ':' || v_user_id::text, 0));
 select coalesce(array_agg(t.id order by t.position, t.id), array[]::uuid[]), count(*) into v_expected_carried_ids, v_expected_carried_count from public.daily_task_items t where t.tenant_id = v_tenant_id and t.team_id = v_team_id and t.user_id = v_user_id and t.logical_date = p_local_date and t.status = 'planned' and t.carried_from_id is not null;
 select count(*) into v_carried_count from unnest(v_carried_ids); select count(distinct carried_id) into v_distinct_carried_count from unnest(v_carried_ids) as carried(carried_id);
 if v_carried_count <> v_distinct_carried_count or v_carried_ids is distinct from v_expected_carried_ids or v_carried_count > cardinality(v_task_titles) then raise exception 'Carried Daily activity identifiers are missing, duplicated, or inaccessible'; end if;
 v_submission_id := public.submit_daily_response(p_run_ids, p_answers, p_local_date);
 update public.daily_task_items task set title = carried.title from (select carried.id, planned.title from unnest(v_carried_ids) with ordinality as carried(id, ordinal) join unnest(v_task_titles) with ordinality as planned(title, ordinal) using (ordinal)) carried where task.tenant_id = v_tenant_id and task.team_id = v_team_id and task.user_id = v_user_id and task.id = carried.id and task.status = 'planned';
 select coalesce(max(t.position), 0) + 1 into v_position from public.daily_task_items t where t.tenant_id = v_tenant_id and t.team_id = v_team_id and t.user_id = v_user_id and t.logical_date = p_local_date;
 insert into public.daily_task_items (tenant_id, team_id, user_id, logical_date, title, position, source_submission_id, source_question_id, source_line_ordinal) select v_tenant_id, v_team_id, v_user_id, p_local_date, planned.title, v_position + planned.ordinal::integer - v_carried_count, v_submission_id, v_planned_question_id, planned.ordinal::integer from unnest(v_task_titles) with ordinality as planned(title, ordinal) where planned.ordinal > v_carried_count;
 return v_submission_id; exception when no_data_found then raise exception 'The Daily team has no active schedule with a valid IANA timezone'; end; $$;
create or replace function public.submit_daily_task_completion(p_team_id uuid, p_logical_date date, p_completed_task_ids uuid[], p_unchecked_resolution text) returns uuid language plpgsql security definer set search_path = '' as $$ declare v_user_id uuid := auth.uid(); v_tenant_id uuid; v_local_now timestamp; v_schedule record; v_task_count integer; v_completed_count integer; v_distinct_completed_count integer; v_unchecked_count integer; v_completion_id uuid; v_next_task_id uuid; v_next_position integer; v_next_logical_date date; v_completed_ids uuid[] := coalesce(p_completed_task_ids, array[]::uuid[]); v_task record; v_outcome text; v_offset integer; begin
 if v_user_id is null or not private.is_internal_user() then raise exception 'An authenticated internal user is required'; end if; select p.tenant_id into strict v_tenant_id from public.profiles p where p.id = v_user_id and p.status = 'active';
 if v_tenant_id is distinct from private.current_tenant_id() or not (private.is_tenant_admin(v_tenant_id) or private.is_team_member(v_tenant_id, p_team_id)) then raise exception 'The selected Daily team is not available to your account'; end if;
 select s.* into strict v_schedule from public.team_daily_schedules s join public.teams t on t.tenant_id = s.tenant_id and t.id = s.team_id where s.tenant_id = v_tenant_id and s.team_id = p_team_id and s.is_active and t.archived_at is null and nullif(btrim(s.timezone_name), '') is not null for share;
 begin v_local_now := clock_timestamp() at time zone v_schedule.timezone_name; exception when invalid_parameter_value then raise exception 'The Daily team timezone is invalid'; end;
 if p_logical_date is null or p_logical_date <> v_local_now::date then raise exception 'The Daily completion date does not match the team local date'; end if; if v_local_now::time < time '16:00' then raise exception 'Daily completion is available after the team local 16:00 cutoff'; end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_tenant_id::text || ':' || p_team_id::text || ':' || p_logical_date::text || ':' || v_user_id::text, 0));
 select c.id into v_completion_id from public.daily_task_completions c where c.tenant_id = v_tenant_id and c.team_id = p_team_id and c.user_id = v_user_id and c.logical_date = p_logical_date; if v_completion_id is not null then return v_completion_id; end if;
 select count(*) into v_completed_count from unnest(v_completed_ids); select count(distinct completed_id) into v_distinct_completed_count from unnest(v_completed_ids) as completed(completed_id); if v_completed_count <> v_distinct_completed_count then raise exception 'Daily completed activity identifiers cannot be duplicated'; end if;
 select count(*) into v_task_count from public.daily_task_items t where t.tenant_id = v_tenant_id and t.team_id = p_team_id and t.user_id = v_user_id and t.logical_date = p_logical_date and t.status = 'planned'; if v_task_count = 0 then raise exception 'There are no planned Daily activities to complete'; end if;
 if exists (select 1 from unnest(v_completed_ids) completed(completed_id) where not exists (select 1 from public.daily_task_items t where t.id = completed.completed_id and t.tenant_id = v_tenant_id and t.team_id = p_team_id and t.user_id = v_user_id and t.logical_date = p_logical_date and t.status = 'planned')) then raise exception 'A completed Daily activity is missing or inaccessible'; end if;
 v_unchecked_count := v_task_count - v_completed_count; if v_unchecked_count > 0 and coalesce(p_unchecked_resolution, '') not in ('delete', 'carry') then raise exception 'Choose delete or carry for every unchecked Daily activity'; end if; if v_unchecked_count = 0 and coalesce(p_unchecked_resolution, 'none') <> 'none' then raise exception 'No unchecked Daily activities require a resolution'; end if;
 if p_unchecked_resolution = 'carry' then for v_offset in 1..7 loop v_next_logical_date := p_logical_date + v_offset; exit when extract(isodow from v_next_logical_date)::smallint = any(v_schedule.scheduled_weekdays); end loop; if v_next_logical_date is null then raise exception 'The Daily team has no next scheduled local date'; end if; end if;
 insert into public.daily_task_completions (tenant_id, team_id, user_id, logical_date, timezone_snapshot) values (v_tenant_id, p_team_id, v_user_id, p_logical_date, v_schedule.timezone_name) returning id into v_completion_id;
 select coalesce(max(t.position), 0) + 1 into v_next_position from public.daily_task_items t where t.tenant_id = v_tenant_id and t.team_id = p_team_id and t.user_id = v_user_id and t.logical_date = v_next_logical_date and t.status = 'planned';
 for v_task in select t.id, t.title, t.position from public.daily_task_items t where t.tenant_id = v_tenant_id and t.team_id = p_team_id and t.user_id = v_user_id and t.logical_date = p_logical_date and t.status = 'planned' order by t.position, t.id for update loop v_next_task_id := null; if v_task.id = any(v_completed_ids) then v_outcome := 'completed'; update public.daily_task_items set status = 'completed' where tenant_id = v_tenant_id and id = v_task.id; elsif p_unchecked_resolution = 'carry' then v_outcome := 'carried'; update public.daily_task_items set status = 'carried' where tenant_id = v_tenant_id and id = v_task.id; insert into public.daily_task_items (tenant_id, team_id, user_id, logical_date, title, position, carried_from_id) values (v_tenant_id, p_team_id, v_user_id, v_next_logical_date, v_task.title, v_next_position, v_task.id) returning id into v_next_task_id; v_next_position := v_next_position + 1; else v_outcome := 'deleted'; update public.daily_task_items set status = 'deleted' where tenant_id = v_tenant_id and id = v_task.id; end if; insert into public.daily_task_completion_items (tenant_id, completion_id, team_id, user_id, task_id, title_snapshot, position, outcome, next_task_id) values (v_tenant_id, v_completion_id, p_team_id, v_user_id, v_task.id, v_task.title, v_task.position, v_outcome, v_next_task_id); end loop; return v_completion_id; exception when no_data_found then raise exception 'The Daily team has no active schedule with a valid IANA timezone'; end; $$;
alter function private.snapshot_daily_run_questions() owner to postgres;
alter function public.submit_daily_response_with_tasks(uuid[], jsonb, date, uuid[]) owner to postgres;
alter function public.submit_daily_task_completion(uuid, date, uuid[], text) owner to postgres;
revoke all on function public.submit_daily_response_with_tasks(uuid[], jsonb, date, uuid[]) from public, anon, authenticated, service_role;
grant execute on function public.submit_daily_response_with_tasks(uuid[], jsonb, date, uuid[]) to authenticated;
revoke execute on function public.submit_daily_response(uuid[], jsonb, date) from authenticated;
revoke all on function public.add_daily_task_items(uuid, date, text[]) from public, anon, authenticated, service_role;
revoke all on function public.submit_daily_task_completion(uuid, date, uuid[], text) from public, anon, authenticated, service_role;
grant execute on function public.submit_daily_task_completion(uuid, date, uuid[], text) to authenticated;;
